use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::net::UdpSocket;
use std::time::{SystemTime, UNIX_EPOCH};

const AES_BLOCK_SIZE: usize = 16;
const DNS_PORT: u16 = 53;
const MAX_LABEL_LEN: usize = 63;

/// Connection pool entry with cached crypto state
struct PoolEntry {
    socket: UdpSocket,
    server_addr: String,
    cipher_key: [u8; 32],
    iv_state: IvState,
    query_count: u64,
}

/// IV generation state machine
struct IvState {
    base_iv: [u8; AES_BLOCK_SIZE],
    counter: u64,
    epoch_offset: u64,
}

impl IvState {
    fn new(seed: u64) -> Self {
        let mut base_iv = [0u8; AES_BLOCK_SIZE];
        let seed_bytes = seed.to_le_bytes();
        base_iv[..8].copy_from_slice(&seed_bytes);
        // Fill upper half with timestamp-derived entropy
        let ts = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos() as u64;
        base_iv[8..16].copy_from_slice(&ts.to_le_bytes());
        IvState {
            base_iv,
            counter: 0,
            epoch_offset: ts,
        }
    }

    /// Derive next IV using counter mode with epoch binding
    fn next_iv(&mut self) -> [u8; AES_BLOCK_SIZE] {
        let mut iv = self.base_iv;
        // XOR counter into first 8 bytes for uniqueness
        let ctr_bytes = self.counter.to_le_bytes();
        for i in 0..8 {
            iv[i] ^= ctr_bytes[i];
        }
        self.counter = self.counter.wrapping_add(1);
        iv
    }

    /// Reset state when connection is returned to pool - generate fresh IV state
    fn reset_for_reuse(&mut self) {
        let ts = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos() as u64;
        // Generate completely new base_iv with fresh entropy
        let mut new_base = [0u8; AES_BLOCK_SIZE];
        let combined = ts.wrapping_mul(0x517cc1b727220a95).wrapping_add(self.counter);
        new_base[..8].copy_from_slice(&combined.to_le_bytes());
        new_base[8..16].copy_from_slice(&ts.to_le_bytes());
        self.base_iv = new_base;
        // Counter continues monotonically - never resets
        self.epoch_offset = ts;
    }
}

pub struct DnsConnectionPool {
    pool: Arc<Mutex<HashMap<String, Vec<PoolEntry>>>>,
    max_per_server: usize,
}

impl DnsConnectionPool {
    pub fn new(max_per_server: usize) -> Self {
        DnsConnectionPool {
            pool: Arc::new(Mutex::new(HashMap::new())),
            max_per_server,
        }
    }

    /// Acquire a connection from the pool or create new
    pub fn acquire(&self, server: &str, key: &[u8; 32]) -> PoolEntry {
        let mut pool = self.pool.lock().unwrap();
        if let Some(entries) = pool.get_mut(server) {
            if let Some(mut entry) = entries.pop() {
                entry.iv_state.reset_for_reuse();
                return entry;
            }
        }
        // Create new connection
        let socket = UdpSocket::bind("0.0.0.0:0").unwrap();
        socket.connect(format!("{}:{}", server, DNS_PORT)).unwrap();
        let seed = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos() as u64;
        PoolEntry {
            socket,
            server_addr: server.to_string(),
            cipher_key: *key,
            iv_state: IvState::new(seed),
            query_count: 0,
        }
    }

    /// Return connection to pool for reuse
    pub fn release(&self, entry: PoolEntry) {
        let mut pool = self.pool.lock().unwrap();
        let entries = pool.entry(entry.server_addr.clone()).or_insert_with(Vec::new);
        if entries.len() < self.max_per_server {
            entries.push(entry);
        }
    }
}

/// Encrypt DNS query payload using AES-CTR with derived IV
pub fn encrypt_dns_query(entry: &mut PoolEntry, query: &[u8]) -> Vec<u8> {
    let iv = entry.iv_state.next_iv();
    entry.query_count += 1;
    // Simulated AES-CTR encryption (in production, use aes crate)
    let mut ciphertext = Vec::with_capacity(AES_BLOCK_SIZE + query.len());
    ciphertext.extend_from_slice(&iv);
    // XOR-based stream cipher simulation for demonstration
    let keystream = generate_keystream(&entry.cipher_key, &iv, query.len());
    for (i, byte) in query.iter().enumerate() {
        ciphertext.push(byte ^ keystream[i]);
    }
    ciphertext
}

fn generate_keystream(key: &[u8; 32], iv: &[u8; AES_BLOCK_SIZE], len: usize) -> Vec<u8> {
    let mut stream = Vec::with_capacity(len);
    let mut block_ctr: u64 = 0;
    while stream.len() < len {
        let mut block_input = [0u8; 32];
        block_input[..16].copy_from_slice(iv);
        block_input[16..24].copy_from_slice(&block_ctr.to_le_bytes());
        // Simple PRF simulation: H(key || iv || counter)
        let mut hash_state: u64 = 0xcbf29ce484222325;
        for &b in key.iter().chain(block_input.iter()) {
            hash_state ^= b as u64;
            hash_state = hash_state.wrapping_mul(0x100000001b3);
        }
        stream.extend_from_slice(&hash_state.to_le_bytes());
        block_ctr += 1;
    }
    stream.truncate(len);
    stream
}

/// Resolve DNS query with encrypted transport
pub fn resolve_encrypted(
    pool: &DnsConnectionPool,
    server: &str,
    key: &[u8; 32],
    domain: &str,
) -> Result<Vec<u8>, String> {
    let mut entry = pool.acquire(server, key);
    let query_bytes = build_dns_query(domain)?;
    let encrypted = encrypt_dns_query(&mut entry, &query_bytes);
    entry.socket.send(&encrypted).map_err(|e| e.to_string())?;
    let mut buf = [0u8; 4096];
    let n = entry.socket.recv(&mut buf).map_err(|e| e.to_string())?;
    pool.release(entry);
    Ok(buf[..n].to_vec())
}

fn build_dns_query(domain: &str) -> Result<Vec<u8>, String> {
    let mut query = Vec::new();
    query.extend_from_slice(&[0x00, 0x01]); // Transaction ID
    query.extend_from_slice(&[0x01, 0x00]); // Flags: standard query
    query.extend_from_slice(&[0x00, 0x01]); // Questions: 1
    query.extend_from_slice(&[0x00; 6]);    // Answer/Auth/Additional: 0
    for label in domain.split('.') {
        let label_len = label.len();
        // Validate label length: DNS labels must be 1..=63 bytes.
        if label_len == 0 || label_len > MAX_LABEL_LEN {
            return Err(format!(
                "invalid DNS label length {} (must be 1..={})",
                label_len, MAX_LABEL_LEN
            ));
        }
        query.push(label_len as u8);
        query.extend_from_slice(label.as_bytes());
    }
    query.push(0x00); // Root label
    query.extend_from_slice(&[0x00, 0x01]); // Type A
    query.extend_from_slice(&[0x00, 0x01]); // Class IN
    Ok(query)
}
